-- P29 repair - the format statement and the evidence must reach the answer.
--
-- DEFECT (found by the 2026-10 audit; see docs/NEXUS_PUZZLE_LOGIC_REPAIR.md):
-- 2026100606_investigation_rebuild_stage4.sql asks the operator to submit the
-- core's identity "the core's name and its class code joined without a space",
-- and then accepts the string NEXUS IS AI - which contains two spaces and, in
-- fact, does not contain a class code joined to a name at all. A team that obeys
-- the printed instruction literally submits NEXUSAI and is rejected; the
-- exact/case-insensitive normaliser collapses inner whitespace but never inserts
-- it, so NEXUSAI can never match NEXUS IS AI.
--
-- The class code the prompt refers to is also never printed on any player-visible
-- card, and the briefing never prints the core's name, so the token had two
-- unshown premises on top of the format contradiction.
--
-- REPAIR: keep the canonical token NEXUS IS AI (case bible :227, matrix :1327,
-- both say "unchanged") and make the gate state the thing it actually accepts.
--   * the briefing now prints the project's name, NEXUS, as the file's own name;
--   * the entity card now prints its two-letter class code, AI, beside the stamp;
--   * the analyst instruction, the operator field, the hints and the evidence all
--     now say the identity is the core's name and what the core is - two words
--     plus the class, read in order - instead of "joined without a space".
-- The team still has to separate the stamped entity card from the blank object
-- card and still has to read the class off the right card; difficulty is
-- unchanged. A second accepted answer NEXUS AI absorbs the one reasonable
-- reading in which the copula is left out, so a faithful team is not punished
-- for punctuation.
--
-- REDACTION: NEXUS and AI are two and five characters respectively; the short
-- token AI is under the three-alphanumeric redaction floor and NEXUS alone never
-- equals the answer, so printing them separately cannot seal the choice. Only the
-- contiguous string NEXUSISAI would match, and no player string carries it.
--
-- Migration history is immutable, so this repairs forward.
-- ============================================================================

UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Vault Delta Core - Declassified Briefing","dataPayload":"DECLASSIFIED BRIEFING, vault delta core terminal, stamped and typed: \"PROJECT NEXUS - You have been reading this file as though it were a place. It is not a database on a disk, and none of your submissions went into storage. The core runs where three inputs meet: one who watches, one who reads, one who acts. Take those three away and nothing happens here at all.\" Below the paragraph, two recovered cards are reproduced side by side: an entity card, and an object card recovered with it.","visualType":"observation","whatTheySee":"A stamped briefing that names the project and redefines the core as a running process, beside an entity card and an object card.","taskPrompt":"Record the briefing exactly, and record the two cards without deciding yet which one belongs to the core.","intermediateOutput":"One briefing naming PROJECT NEXUS and defining the core as running where three inputs meet; two recovered cards."},"analyst":{"role":"ANALYST","screenTitle":"Entity Classifier - One Card Is a Misfile","dataPayload":"CLASSIFIER: one of the two cards is the institution''s own blank object card - a database record slip, recovered from the same sleeve but carrying no entity stamp, no class code and no pulse reading: it describes a thing that is merely stored, and this core does not store. The other card carries an entity stamp reading PROJECT NEXUS, a two-letter class code stamped as AI, and a pulse reading of three sources with no single source. The briefing says the core runs where the observers of the file cover its three inputs, which is why the core cannot be switched off: it is not a thing. The stamped card''s class code is the core''s kind, not its name; the name is the project the briefing stamps.","visualType":"document-forensics","whatTheySee":"A classifier separating the blank object card from the entity card stamped PROJECT NEXUS with class code AI and a three-source reading.","taskPrompt":"Decide which card belongs to the core, then read the core''s name from the briefing and its kind from the stamped card''s class code.","intermediateOutput":"The object card is a misfile; the stamped card reads PROJECT NEXUS with class code AI and a three-source reading."},"operator":{"role":"OPERATOR","screenTitle":"Mainframe Query - Entity Identity","dataPayload":"MAINFRAME QUERY: ENTITY IDENTITY: [ _ _ _ ... ]. The query expects the core''s name and then what the core is, as plain words in order, separated by a single space: the name the briefing stamps, then the kind the stamped card''s class code gives. The blank object card stays on the screen beside the field: it was never the answer.","visualType":"terminal","whatTheySee":"An entity identity field above two cards, one stamped, one blank.","taskPrompt":"Submit the entity identity: the core''s name, then what the core is, as words separated by a single space.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The mainframe entity identity field, the declassified briefing, the stamped entity card with its class code, and the blank object card that never belonged with them.","operatorTaskDescription":"The Observer records the briefing and both cards; the Analyst identifies the blank object card as a misfile and the stamped entity card as the core''s record; the Operator submits the core''s name followed by what the core is, and submits it.","requiredDiscoveries":{"observerDiscovery":"Records the briefing verbatim and both cards, including both class codes, without choosing between them.","analystDiscovery":"Rejects the blank object card and takes the name and the class code from the stamped entity card, which reports three sources and no single source."}},"coordinationChain":{"observerProduces":"Observer reports the briefing, the entity card and the object card as found.","analystTransforms":"Analyst discards the object card as a misfile and reads the name and class code off the entity card.","operatorExecutes":"Operator submits the core name and its kind together, unlocking Meta M04."},"hints":["Two cards were recovered from the same sleeve but only one is stamped as an entity. A blank object card with no class code describes a thing that is stored, and the briefing says this core stores nothing.","The briefing names the project - it is what this whole file has been about - and the stamped card gives a two-letter class code saying what the core is, with a pulse reading of three sources.","Put the briefing''s name first, then what the card''s class code says the core is, as two separate words with a single space between them; the mainframe field wants the identity, not a sentence."],"narrativeObjective":"Reclassify the core from a place that stores answers to a process that runs only while three people run it.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"NEXUS IS AI","acceptedAnswers":["NEXUS AI"],"validationMethod":"case_insensitive","fullSolution":"The declassified briefing names the project NEXUS and says the core is not a database on a disk but runs where three inputs meet. Of the two recovered cards, the blank object card carries no entity stamp, no class code and no pulse reading and is a misfile; the stamped entity card carries the name PROJECT NEXUS, class code AI and a pulse reading of three sources with no single source. The core''s identity is the name the briefing stamps followed by what the stamped card''s class code says the core is: NEXUS IS AI."}',
  metadata = '{"type":"NARRATIVE_INVESTIGATION","difficulty":4,"time":"8m","storyReveal":"The terminal speaks: NOW YOU KNOW WHAT I AM. BUT DO YOU KNOW WHAT YOU ARE?","locationClue":{"format":"Poetic","clueText":"LINA''S NOTE: \"Step to the Core Declassification Vault behind reinforced blast doors.\"","solution":"Vault Delta Core","nextPhysicalLocation":"[ENGINEERING BLOCK] - Vault Delta Core","nextQrNode":"QR-NODE-30","explanation":"Points to Vault Delta Core for the meta."},"evidenceUnlocked":{"id":"EVID-P29","category":"Audio","title":"Dictaphone Memo REC-20: The Mirror Entity","state":"RECOVERED","timestamp":"Stage 4","source":"Vault Delta door frame","content":"They wanted a machine they could weaponize. But I built the core so it cannot run unless three human hearts supply the beat. Stage 5 awaits at the transmitter spire."},"whyTeamworkMatters":"Only the observer can read the briefing and both cards; only the analyst can reject the misfile and read the name and class code; only the operator can enter the identity. Rejecting the blank card is itself a role discovery.","feeds":"P28"}'
